"""Excel data sampler with random, stratified, and systematic strategies."""

import argparse
import random
import sys
from pathlib import Path

import openpyxl


def load_workbook(path):
    wb = openpyxl.load_workbook(path, read_only=True, data_only=True)
    ws = wb.active
    rows = list(ws.iter_rows(values_only=True))
    wb.close()
    if not rows:
        raise ValueError("Excel file is empty")
    headers = [str(h) if h is not None else f"col_{i}" for i, h in enumerate(rows[0])]
    records = []
    for row in rows[1:]:
        record = {}
        for i, val in enumerate(row):
            key = headers[i] if i < len(headers) else f"col_{i}"
            record[key] = val
        records.append(record)
    return headers, records


def save_workbook(headers, records, path):
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.append(headers)
    for record in records:
        ws.append([record.get(h) for h in headers])
    wb.save(path)
    print(f"Wrote {len(records)} rows to {path}", file=sys.stderr)


def sample_random(records, n, seed=None):
    rng = random.Random(seed)
    if n >= len(records):
        return list(records)
    return rng.sample(records, n)


def sample_stratified(records, n, stratify_col, seed=None):
    rng = random.Random(seed)
    groups = {}
    for rec in records:
        key = rec.get(stratify_col, "unknown")
        groups.setdefault(key, []).append(rec)

    total = len(records)
    result = []
    for group in groups.values():
        k = max(1, round(n * len(group) / total))
        result.extend(rng.sample(group, min(k, len(group))))

    if len(result) > n:
        result = rng.sample(result, n)
    return result


def sample_systematic(records, n, seed=None):
    rng = random.Random(seed)
    if n >= len(records):
        return list(records)
    step = len(records) / n
    start = rng.uniform(0, step)
    indices = [int(start + i * step) for i in range(n)]
    return [records[i] for i in indices]


STRATEGIES = {
    "random": sample_random,
    "stratified": sample_stratified,
    "systematic": sample_systematic,
}


def main():
    parser = argparse.ArgumentParser(
        description="Sample rows from an Excel file using different strategies."
    )
    parser.add_argument("input", help="Path to input Excel file (.xlsx)")
    parser.add_argument("n", type=int, help="Number of rows to sample")
    parser.add_argument(
        "-m",
        "--method",
        choices=STRATEGIES,
        default="random",
        help="Sampling strategy (default: random)",
    )
    parser.add_argument(
        "-s",
        "--stratify-column",
        help="Column to stratify by (required for stratified sampling)",
    )
    parser.add_argument("-o", "--output", help="Output Excel path (default: <input>_sample.xlsx)")
    parser.add_argument("--seed", type=int, help="Random seed for reproducibility")
    parser.add_argument(
        "--sheet", default=None, help="Sheet name to read (default: active sheet)"
    )
    args = parser.parse_args()

    if args.method == "stratified" and not args.stratify_column:
        parser.error("--stratify-column is required for stratified sampling")

    if args.n <= 0:
        print("Error: n must be a positive integer", file=sys.stderr)
        sys.exit(1)

    headers, records = load_workbook(args.input)
    print(f"Loaded {len(records)} rows, {len(headers)} columns", file=sys.stderr)

    if args.stratify_column and args.stratify_column not in headers:
        print(
            f"Error: column '{args.stratify_column}' not found. Available: {headers}",
            file=sys.stderr,
        )
        sys.exit(1)

    kwargs = {"records": records, "n": args.n, "seed": args.seed}
    if args.method == "stratified":
        kwargs["stratify_col"] = args.stratify_column

    sampled = STRATEGIES[args.method](**kwargs)
    print(
        f"Sampled {len(sampled)} rows using '{args.method}' strategy",
        file=sys.stderr,
    )

    output = args.output or str(Path(args.input).stem) + "_sample.xlsx"
    save_workbook(headers, sampled, output)


if __name__ == "__main__":
    main()
